class Spell {
  constructor(name, manaCost) {
    this.name = name;
    this.manaCost = manaCost;
  }

  cast() {
    return `${this.name} spell is cast with ${this.manaCost} mana.`;
  }
}

class Fireball extends Spell {
  constructor(name, manaCost, damage) {
    super(name, manaCost);
    this.damage = damage;
  }

  cast() {
    return `${this.name} deals ${this.damage} damage!`;
  }
}

class Heal extends Spell {
  constructor(name, manaCost, healingAmount) {
    super(name, manaCost);
    this.healingAmount = healingAmount;
  }

  cast() {
    return `${this.name} restores ${this.healingAmount} health!`;
  }
}

// Test your classes:
const fireball = new Fireball("Greater Fireball", 30, 75);
const minorHeal = new Heal("Minor Heal", 15, 50);

console.log(fireball.cast());
console.log(minorHeal.cast());

